changeSet.sql:
CREATE TABLE notification_recipients ( id BIGSERIAL PRIMARY KEY, notification_id BIGINT NOT NULL REFERENCES notifications(id) ON DELETE CASCADE, recipient_kind VARCHAR(16) NOT NULL CHECK (recipient_kind IN ('user', 'team', 'role')), -- user id (kind=user) or team id (kind=team); NULL for role. recipient_id INTEGER NULL, -- role value (kind=role); NULL for user/team. recipient_role VARCHAR(32) NULL );
-- A user sees a notification when a recipient row matches their -- own id, one of their roles, or one of their teams. These two -- indexes serve that OR directly. CREATE INDEX idx_notification_recipients_id ON notification_recipients (recipient_kind, recipient_id); CREATE INDEX idx_notification_recipients_role ON notification_recipients (recipient_kind, recipient_role);
-- Keep each target unique within a notification. COALESCE folds -- the nullable id/role columns so (user,5) and (role,'app_admin') -- each hash to one slot instead of colliding on NULLs. CREATE UNIQUE INDEX uq_notification_recipients_target ON notification_recipients (notification_id, recipient_kind, COALESCE(recipient_id, 0), COALESCE(recipient_role, ''));
